contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        require(amount > 0);

        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 ownerBefore = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted ? c.balanceOf(owner) == ownerBefore : c.balanceOf(owner) == ownerBefore - amount);
    }
}

